from decimal import Decimal, ROUND_HALF_UP

def payable(lines, rebate):
    subtotal = sum(Decimal(str(line['price'])) * line['quantity'] for line in lines)
    return (subtotal * (1 - Decimal(str(rebate)))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

def overdue(invoices, today):
    return [item for item in invoices if not item['paid'] and item['due'] < today]

