def unique(events):
    seen = set()
    for event in events:
        if event['id'] not in seen:
            seen.add(event['id'])
            yield event

def attempt(operation, retries, pause):
    for index in range(retries):
        try:
            return operation()
        except TimeoutError:
            if index + 1 == retries:
                raise
            pause(2 ** index)

